// ── GitHub, from the browser ────────────────────────────────────────────────────────────────

async function gh(method: string, path: string, body?: Json): Promise<Json> {
  const token = await githubToken();

  if (!token) {
    throw new Error('No GitHub token is set. Add one in Settings.');
  }

  const response = await fetch(`https://api.github.com${ path }`, {
    method,
    headers: {
      authorization: `Bearer ${ token }`,
      accept:        'application/vnd.github+json',
      ...(body ? { 'content-type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();

  if (!response.ok) {
    throw new Error(`GitHub ${ method } ${ path } answered ${ response.status }: ${ text.slice(0, 300) }`);
  }

  return text ? JSON.parse(text) : null;
}

/**
 * Approve the PR now. Pending local comments are discarded on the way, as the harness does:
 * approving is saying there is nothing more to say.
 */
export async function approvePr(num: number, body = '', repo = DEFAULT_REPO): Promise<{ url: string; discarded: number }> {
  const pending = (await listComments(num)).filter((c) => !c.submitted_at);

  for (const c of pending) {
    await deleteComment(num, c.id);
  }

  const review = await gh('POST', `/repos/${ repo }/pulls/${ num }/reviews`, { event: 'APPROVE', ...(body ? { body } : {}) });

  return { url: review?.html_url || '', discarded: pending.length };
}

/**
 * Post every approved local comment to GitHub as one review, as comments (the default), as a
 * request for changes, or as an approval with the comments on it.
 *
 * All of them have to be approved first - that is what marking a comment good is for - and the
 * PR-level ones become the review's body while the line ones ride as inline comments. Then they
 * are stamped submitted here, so the next review starts from nothing.
 *
 * Their anchors are settled against the diff on the way - see `review-anchors.mjs` - because
 * GitHub rejects a whole review over one line it cannot place and will not say which.
 */
export async function submitReview(num: number, repo = DEFAULT_REPO, event: 'COMMENT' | 'APPROVE' | 'REQUEST_CHANGES' = 'COMMENT', note = ''): Promise<{ url: string | null; posted: number; moved: string[] }> {
  const comments = (await listComments(num)).filter((c) => !c.submitted_at);

  if (!comments.length) {
    throw new Error('There are no comments to submit.');
  }

  const pending = comments.filter((c) => c.status !== 'approved');

  if (pending.length) {
    throw new Error(`${ pending.length } comment${ pending.length === 1 ? ' is' : 's are' } still pending. Mark them good, or delete them, before submitting.`);
  }

  /*
   * Where each comment may land, settled before anything is uploaded.
   *
   * GitHub takes an inline comment only on a line its diff contains, and refuses the entire
   * review over a single miss - `422 Line could not be resolved`, naming nothing. That used to
   * surface here as the raw 422, after the evidence had already been uploaded, with no way to
   * tell which of five findings was the one that was one line off.
   */
  const files = await gh('GET', `/repos/${ repo }/pulls/${ num }/files?per_page=100`);
  const { resolved, moved, lost } = resolveAnchors(comments, diffAnchors(files || []));

  if (lost.length) {
    throw new Error(lostMessage(lost));
  }

  // Evidence goes with the comment it belongs to. A text file - a test, a log - is read from the
  // agent's workspace and inlined as a code block, which is how a reviewer wants to read it
  // anyway. An image or a recording is uploaded to GitHub's user-attachments CDN through the
  // shared browser that holds the github.com session (dev-api does the driving) and embedded, so
  // the reviewer sees the evidence rather than a sentence naming a path only this cluster can
  // reach.
  //
  // Everything is resolved before the review is posted, so an upload that fails takes the whole
  // submit with it. That is deliberate: a review that lands with its evidence missing cannot be
  // repaired - the comments are public by then, and re-submitting would double them.
  const withEvidence = await Promise.all(resolved.map(async({ comment: c, anchor }) => ({ ...c, anchor, body: await bodyWithEvidence(num, c, repo) })));
  const inline = withEvidence.filter((c) => c.path);
  /*
   * The review's own body: what was typed when it was submitted, then the findings that are
   * about the pull request rather than a line of it.
   *
   * `note` first, because it is the thing being said about the review as a whole and the
   * PR-level findings are evidence for it. A review could only ever say something at the top by
   * having a finding filed with no path, which meant the one thing most reviews want to say -
   * a sentence about the change - had to be filed as a finding first or not said at all.
   */
  const body = [String(note || '').trim(), ...withEvidence.filter((c) => !c.path).map((c) => c.body)]
    .filter(Boolean)
    .join('\n\n');
  const review = await gh('POST', `/repos/${ repo }/pulls/${ num }/reviews`, {
    event,
    ...(body ? { body } : {}),
    comments: inline.map((c) => ({
      path: c.path,
      line: c.anchor.line ?? undefined,
      side: c.anchor.side,
      ...(c.anchor.start_line ? { start_line: c.anchor.start_line, start_side: c.anchor.side } : {}),
      body: c.body,
    })),
  });
  const stamp = new Date().toISOString();

  for (const c of comments) {
    await api(`/my-work/pr/${ num }/comments/${ c.id }`, { method: 'PUT', body: JSON.stringify({ submitted_at: stamp }) });
  }

  return {
    url: review?.html_url || null, posted: comments.length, moved,
  };
}

/**
 * Approve with nothing said.
 *
 * Separate from `submitReview` because that one refuses an empty review - rightly: posting a
 * review with no comments and no verdict is a no-op that looks like a success. Here the verdict
 * *is* the content, so there is nothing to refuse.
 *
 * Findings left in the workspace are not touched. They are drafts, they are yours, and a button
 * labelled Approve has no business deleting them - so they stay where they are and the card
 * says they were not sent. The old prompt told an agent they were "discarded", which an agent
 * could have read as `rm`.
 */
export async function approveWithNothing(num: number, repo = DEFAULT_REPO): Promise<{ url: string | null; unsent: number }> {
  const unsent = (await listComments(num).catch(() => [] as LocalComment[])).filter((c) => !c.submitted_at).length;
  const review = await gh('POST', `/repos/${ repo }/pulls/${ num }/reviews`, { event: 'APPROVE' });

  return { url: review?.html_url || null, unsent };
}

/**
 * A review that is words and a verdict and nothing else: what the Focus PR sheet posts.
 *
 * Not `submitReview`, which posts the workspace's findings and stamps them sent - a review typed
 * into the sheet has nothing to do with those, and must not sweep them up or mark them gone.
 * GitHub wants words for a comment and for a request for changes; an approval may be bare.
 */
export async function reviewWithBody(num: number, repo: string, event: 'COMMENT' | 'APPROVE' | 'REQUEST_CHANGES', body: string): Promise<string> {
  const said = String(body || '').trim();

  if (!said && event !== 'APPROVE') {
    throw new Error('a comment or a request for changes needs something said in it');
  }
  const review = await gh('POST', `/repos/${ repo }/pulls/${ num }/reviews`, { event, ...(said ? { body: said } : {}) });

  forgetPrDetail(num, repo);

  return review?.html_url || '';
}

/** Reply to a comment on GitHub. There is no draft for a reply: it lands in the thread now. */
/**
 * Change or drop a review comment on GitHub, yours, wherever it is in its thread.
 *
 * These are the two halves a pending reply needs that a filed one does not have here: a draft
 * is something you are still writing, and until the review goes out it is yours to fix or throw
 * away. GitHub takes both on a comment in a pending review exactly as it does on a posted one -
 * same endpoints, no separate pending API - so this is the whole of it.
 *
 * `id` is the comment's, not the pull request's: `/pulls/comments/:id` is addressed by comment
 * across the repository, which is why the number here is nothing like the one in the paths above.
 */
export async function editReviewComment(id: number, body: string, repo = DEFAULT_REPO): Promise<void> {
  await gh('PATCH', `/repos/${ repo }/pulls/comments/${ id }`, { body });
}

export async function deleteReviewComment(id: number, repo = DEFAULT_REPO): Promise<void> {
  await gh('DELETE', `/repos/${ repo }/pulls/comments/${ id }`);
}

/** A reply an agent drafted into a thread, as dev-api keeps it (`/my-work/pr/<n>/reply-draft`). */
export interface ReplyDraft {
  id: number;
  inReplyTo: number;
  body: string;
}

/**
 * Send an agent's drafted reply: into its thread on GitHub now, then off the drafts. In that
 * order, so a send that fails leaves the draft where it was rather than losing it.
 */
export async function sendReplyDraft(num: number, draft: ReplyDraft, body = draft.body, repo = DEFAULT_REPO): Promise<{ id: number; url: string }> {
  const sent = await replyToComment(num, draft.inReplyTo, body, repo);

  await discardReplyDraft(num, draft.id);

  return sent;
}

/** Change a drafted reply's wording. It stays a draft: this posts nothing. */
export async function updateReplyDraft(num: number, id: number, body: string): Promise<void> {
  await api(`/my-work/pr/${ num }/reply-drafts/${ id }`, { method: 'PUT', body: JSON.stringify({ body }) });
}

export async function discardReplyDraft(num: number, id: number): Promise<void> {
  await api(`/my-work/pr/${ num }/reply-drafts/${ id }`, { method: 'DELETE' });
}

export async function replyToComment(num: number, commentId: number, body: string, repo = DEFAULT_REPO): Promise<{ id: number; url: string }> {
  const reply = await gh('POST', `/repos/${ repo }/pulls/${ num }/comments/${ commentId }/replies`, { body });

  return { id: reply?.id, url: reply?.html_url || '' };
}

/**
 * A message on the pull request itself, under the conversation rather than on a line.
 *
 * A separate call because GitHub keeps the two in separate places: a review comment is on a
 * line and replies go into its thread (above), while the discussion under a pull request is
 * issue comments and has no threads at all. Replying to one through the review-comment endpoint
 * is a 404, which is what a single "reply" would have done for every message in the discussion.
 */
export async function commentOnPr(num: number, body: string, repo = DEFAULT_REPO): Promise<{ id: number; url: string }> {
  const made = await gh('POST', `/repos/${ repo }/issues/${ num }/comments`, { body });

  return { id: made?.id, url: made?.html_url || '' };
}

/**
 * One message as a markdown quote, the way GitHub's own Quote reply writes it.
 *
 * Every line prefixed, empty lines included - a blank line without the marker ends the
 * blockquote, so a quoted two-paragraph comment would come out as one quote and one reply of
 * somebody else's words. A blank line after it, so what gets typed next is not inside it.
 */
export function quoted(body: string): string {
  return `${ String(body || '').replace(/\r/g, '').split('\n').map((line) => `> ${ line }`.trimEnd())
    .join('\n') }\n\n`;
}

const CODE_LANG: Record<string, string> = {
  '.ts': 'ts', '.js': 'js', '.mjs': 'js', '.vue': 'vue', '.json': 'json', '.yaml': 'yaml', '.yml': 'yaml', '.sh': 'bash', '.log': 'text', '.txt': 'text', '.md': 'md',
};
const ATTACH_MARKER = /\[\[attach:([^\]]+)\]\]/g;
/*
 * How much of a text attachment goes into the comment itself.
 *
 * It was 60,000 characters, which is not a quotation - it is the whole file. A GitHub comment
 * holds 65,536, so one log could fill the comment on its own and push the finding that was
 * supposed to be the point of it off the top; two of them cannot be posted at all. And a
 * reviewer opening a thread to read one sentence about one line does not want a run's entire
 * output above it.
 *
 * 4,000 is a long look at a test failure and still something a person scrolls past rather than
 * through. What does not fit is said rather than silently dropped, with the path, because the
 * file is in the workspace and can be read there.
 */
const MAX_INLINE = 4_000;

/**
 * A screenshot or a recording as markdown GitHub will render, having put the bytes on its CDN.
 *
 * The two shapes are not interchangeable: a still is markdown image syntax, and a recording is a
 * bare `user-attachments` URL on a line of its own, which GitHub turns into a player. Wrapping a
 * recording in image or link syntax is what makes it render as a dead link instead.
 */
async function uploadedEmbed(num: number, item: LocalAttachment, repo: string): Promise<string> {
  if (!item.found) {
    throw new Error(`The evidence on one comment is gone: \`${ item.path }\` is no longer in the workspace. Re-record it or remove it from the comment, then submit again.`);
  }

  let href = '';

  try {
    href = (await api(`/my-work/pr/${ num }/upload`, { method: 'POST', body: JSON.stringify({ path: item.path, repo }) }) as Json).href;
  } catch (e: unknown) {
    throw new Error(`${ item.name } could not be uploaded to GitHub, so nothing was submitted: ${ (e as Error)?.message || e }`);
  }

  if (!href) {
    throw new Error(`${ item.name } could not be uploaded to GitHub, so nothing was submitted.`);
  }

  // The caption is not posted. It is how the person and the agent tell two screenshots apart
  // while they are going through them here - "before", "after in edit mode" - and on GitHub it
  // reads as a line of our own commentary above somebody else's evidence, in italics, saying
  // what the two pictures underneath already show. The images go up bare.
  return item.kind === 'image' ? `![${ item.name }](${ href })` : href;
}

async function bodyWithEvidence(num: number, c: LocalComment, repo: string): Promise<string> {
  const items = c.attachments || [];

  if (!items.length) {
    return c.body;
  }

  let body = c.body;
  const trailing: string[] = [];

  for (const item of items) {
    const ext = item.name.slice(item.name.lastIndexOf('.')).toLowerCase();
    let embed = '';

    if (CODE_LANG[ext] && item.found) {
      const text = await fetch(artifactUrl(num, item.path), { credentials: 'same-origin' }).then((r) => (r.ok ? r.text() : '')).catch(() => '');

      if (text) {
        const fenced = (t: string) => `\`\`\`${ CODE_LANG[ext] }\n${ t.replace(/\`\`\`/g, '\u0060\u0060\u0060') }\n\`\`\``;
        // The tail, not the head: a log's reason for existing is at the end of it.
        const kept = text.length <= MAX_INLINE ? text : text.slice(-MAX_INLINE);
        const trimmed = kept.length < text.length
          ? `_The last ${ kept.length } of ${ text.length } characters of \`${ item.name }\`; the whole file is in the workspace at \`${ item.path }\`._\n\n`
          : '';

        // Folded, so a comment is its finding with the evidence under it rather than the other
        // way round. GitHub renders <details> in a comment and opens it on a click.
        embed = `${ trimmed }<details><summary>${ item.name }</summary>\n\n${ fenced(kept) }\n\n</details>`;
      }
    }

    if (!embed && (item.kind === 'image' || item.kind === 'video')) {
      embed = await uploadedEmbed(num, item, repo);
    }

    if (!embed) {
      // Not a caption but a stand-in: this is evidence that could not be embedded, and a
      // comment that silently dropped it would read as an assertion with nothing behind it.
      embed = `_${ item.kind } \`${ item.name }\`, recorded in the workspace at \`${ item.path }\`_`;
    }

    let used = false;

    body = body.replace(ATTACH_MARKER, (whole, ref) => {
      if (ref.trim() !== item.name && ref.trim() !== item.path) {
        return whole;
      }
      used = true;

      return embed;
    });

    if (!used) {
      trailing.push(embed);
    }
  }

  return trailing.length ? `${ body }\n\n${ trailing.join('\n\n') }` : body;
}

/** Squash-merge, after checking CI is not red or still running. */
export async function mergePr(num: number, repo = DEFAULT_REPO): Promise<{ sha: string }> {
  const meta = await gh('GET', `/repos/${ repo }/pulls/${ num }`);
  const sha = meta.head?.sha;

  if (sha) {
    const [checks, status] = await Promise.all([
      gh('GET', `/repos/${ repo }/commits/${ sha }/check-runs?per_page=100`).catch(() => null),
      gh('GET', `/repos/${ repo }/commits/${ sha }/status`).catch(() => null),
    ]);
    const runs: Json[] = checks?.check_runs || [];
    const red = runs.some((r) => ['failure', 'timed_out'].includes(r.conclusion)) || (status?.statuses || []).some((s: Json) => ['failure', 'error'].includes(s.state));
    const running = runs.some((r) => r.status !== 'completed') || (status?.statuses || []).some((s: Json) => s.state === 'pending');

    if (red) {
      throw new Error('CI is red on this PR. Fix or re-run it first.');
    }
    if (running) {
      throw new Error('CI is still running on this PR. Wait for it.');
    }
  }

  const result = await gh('PUT', `/repos/${ repo }/pulls/${ num }/merge`, { merge_method: 'squash', sha });

  return { sha: result?.sha || '' };
}

export interface MergeStep { step: string; ok: boolean; note?: string }

/** Approve, squash-merge, delete the branch: the harness's "Approve & merge" for a bot PR. */
export async function approveAndMerge(num: number, repo = DEFAULT_REPO): Promise<{ steps: MergeStep[] }> {
  const steps: MergeStep[] = [];
  const meta = await gh('GET', `/repos/${ repo }/pulls/${ num }`);

  await gh('POST', `/repos/${ repo }/pulls/${ num }/reviews`, { event: 'APPROVE' });
  steps.push({ step: 'approve', ok: true });
  await mergePr(num, repo);
  steps.push({ step: 'merge', ok: true });

  const branch = meta.head?.ref;
  const fork = meta.head?.repo?.full_name && meta.head.repo.full_name !== repo;

  if (branch && !fork) {
    try {
      await gh('DELETE', `/repos/${ repo }/git/refs/heads/${ branch }`);
      steps.push({ step: 'delete-branch', ok: true });
    } catch (e: Json) {
      const gone = /422|Reference does not exist/.test(String(e?.message));

      steps.push({ step: 'delete-branch', ok: gone, note: gone ? 'already deleted' : String(e?.message || e).slice(0, 120) });
    }
  } else {
    steps.push({ step: 'delete-branch', ok: true, note: 'branch is on a fork - left alone' });
  }

  return { steps };
}

/** Re-run every failed workflow run behind a PR's red checks. */
export async function rerunFailedJobs(pr: { repo: string; runs: Json[] }): Promise<number> {
  await Promise.all((pr.runs || []).map((run) => rerunFailed(pr.repo, run)));

  return (pr.runs || []).length;
}

// ── Agent actions ───────────────────────────────────────────────────────────────────────────

/**
 * The harness's prompts, verbatim.
 *
 * The harness built its project containers so that these were all a skill needed to be told;
 * workspace-tools.ts builds the workspace's pod the same way, so they are the same words here,
 * em dashes and all. `$CLAUDE_HARNESS_API` is set in the pod (the App's env and the seed's
 * settings.json) to the in-cluster API, which answers the same routes.
 */
const API_HINT = '$CLAUDE_HARNESS_API/my-work/pr';

export function reviewPrompt(pr: number, repo = DEFAULT_REPO): string {
  // review-prompt.mjs, which dev-api starts automated reviews with too.
  return sharedReviewPrompt(pr, repo);
}

export function fixPrompt(num: number, repo = DEFAULT_REPO): string {
  // Prose, not `/my-issue-fix` - see reviewPrompt.
  return `Use the my-issue-fix skill to fix ${ repo } issue #${ num } — this project was created for it.`;
}

/**
 * The workspace this work needs, made if it is not there.
 *
 * `repo` is written into the Installation, and that is the whole of what makes a workspace for
 * another repository work. Everything downstream reads it from there - the registrar, the page,
 * the rail, every GitHub call - and nothing can infer it, because `pr-1208` says a number and
 * not whose. A workspace created without it asks rancher/dashboard about somebody else's pull
 * request, is told 404, and has no stages, no rail and nothing to press. `lte-pr-1202` and
 * `lte-pr-1208` both arrived that way, and every caller below has known the repository all
 * along without passing it.
 *
 * Only when it is not the default, so an ordinary dashboard workspace's values stay exactly as
 * they were rather than gaining a key that says what omission already said.
 */
export async function ensureWorkspace(store: Store, name: string, title = '', repo = DEFAULT_REPO, ask = true): Promise<boolean> {
  const existing = (await listAllWorkspaces().catch(() => [])).some((workspace) => workspace.name === name);

  if (!existing) {
    // Ask which Rancher to run on (ranchers.ts), defaulting to the last choice. Cancelling the
    // picker throws RancherPickCancelled, which aborts the start before anything is created. The
    // title - the issue or PR this was started from - rides along so the workspace list can show
    // it beside the `pr-<n>` / `issue-<n>` name.
    // Which kind of workspace the name says it is. `workspaceFor` decides that above: work that
    // already has a workspace keeps whichever kind it is, and new work is leased.
    // `ask` false is an automation: the Rancher last chosen, with no picker (lastRancherValues).
    const values = { ...(ask ? await defaultRancherValues(store) : await lastRancherValues()), ...(repo && repo !== DEFAULT_REPO ? { repo } : {}) };

    await createWorkspace(store, name, isLte(name) ? LTE_APP : DEFAULT_APP, undefined, values, title);
  }

  return !existing;
}

/**
 * A conversation in the workspace with a prompt queued, the workspace's pod made ready for it.
 *
 * The registration is immediate; the rest waits for the pod, which for a workspace made a
 * moment ago is minutes away (a clone and a yarn install), and runs in the background so the
 * button that asked for this comes back now. The pane, docked wherever it was asked for,
 * shows the pod arriving and then the prompt starting. `onNote` hears where it has got to.
 */
/**
 * Put a prompt into a conversation that already exists.
 *
 * Reattaching used to mean handing the existing conversation back and sending nothing - so the
 * second press of Fix it, Review, or any of these reported that a conversation had started and
 * delivered no instruction to it at all. The conversation was right there, busy or idle, and
 * the prompt went nowhere.
 *
 * Which way it goes depends on whether the pane is running. A live pane is typed into, because
 * the queue file is only read when claude starts; a pane that has finished (or never started)
 * gets the queue and then a start, which is the same path a new conversation takes.
 */
async function deliverTo(workspace: string, conversation: ProjectConversation, prompt: string): Promise<void> {
  const alive = (await conversationStates().catch(() => [])).find((c) => c.id === conversation.id)?.alive;

  if (alive) {
    await sendToPane(conversation.id, prompt);

    return;
  }
  await queuePrompt(conversation.attach, prompt);
  await startPaneDetached(workspace, conversation.id).catch(() => {});
}

/**
 * Start the workspace, if an action has been pressed on one that is stopped.
 *
 * A workspace with nothing going on in it is spun down after a while (workspace-status.ts), and
 * one can be stopped by hand as well. Nothing then creates its pod, so the wait below was a wait
 * for something that was never coming: the conversation existed, the prompt sat in its queue,
 * and the pane never started - which reads exactly like a button that did nothing.
 *
 * Quiet on failure, like everything else on this path: the conversation is already made, and a
 * workspace that cannot be started says so through the pod that never arrives.
 */
async function wakeWorkspace(workspace: string, onNote?: (note: string) => void): Promise<void> {
  const known = await getWorkspace(workspace).catch(() => null);

  if (!known || known.replicas > 0) {
    return;
  }

  onNote?.('the workspace was stopped; starting it');
  await setWorkspaceRunning(workspace, true, known.cluster || undefined).catch((e: Json) => {
    onNote?.(`the workspace could not be started: ${ e?.message || e }`);
  });
}

async function openWith(workspace: string, title: string, prompt: string, ctx?: WorkspaceContext, onNote?: (note: string) => void, store?: Store, from: ConversationOrigin = '', context = ''): Promise<ProjectConversation> {
  // `from` is where this was started, and it goes into the conversation's id rather than only
  // into its title: a title is renamed, by a person or by claude, and the id is what a
  // transcript, a tmux session and a pane record are all filed under. See conversation-id.mjs.
  const conversation = await startConversation(workspace, title, '', '', from);

  // Context given quietly, before anything is queued: the pane starts below, and the hook hands
  // the context over with the first prompt it sees, which must not beat this write. If it cannot
  // be staged it is said instead, the way every discussion used to open - visible, but there.
  if (context) {
    const staged = await stageSessionContext(conversation.attach?.id || conversation.id, context).then(() => true, (e: Json) => {
      note('dev', 'staging the discussion context failed', e);

      return false;
    });

    if (!staged) {
      prompt = [context, prompt].filter(Boolean).join('\n\n');
    }
  }

  // Queue the opening prompt now, up front, not after the workspace is ready. It goes into the
  // agent pod (queueSessionPrompt writes `<agent home>/.queue/<id>`), which is always up and has
  // nothing to do with the workspace's own pod - so it is waiting from the moment the
  // conversation exists. The pane reads it on its first start, and the workspace view holds that
  // start back until the pod is fully up (WorkspaceConversations, fullyUp), so by the time claude
  // runs the prompt the checkout it acts on is there. Queuing it in `prepare` instead - after the
  // minutes a first `ensureWorkspaceReady` takes - is what let a pane start first and sit at an
  // empty prompt. Queued through the agents extension because that is where every pane runs.
  await (prompt ? queuePrompt(conversation.attach, prompt) : Promise.resolve()).catch((e: Json) => {
    onNote?.(`the prompt could not be queued: ${ e?.message || e }`);
    note('dev', 'queuing the opening prompt failed', e);
  });

  const prepare = async() => {
    onNote?.('preparing the workspace (skills, gh, browser)');
    await ensureWorkspaceReady(workspace, ctx);
    // And started, here, rather than when somebody opens the conversation. The pane runs in
    // the agent pod (shell.sh in `start` mode: the tmux session made detached, claude reading
    // the queued prompt), so a fix or a review begun and left alone is finished by the time
    // anyone comes back to it. Opening the conversation later attaches to the same pane. The
    // workspace is prepared by now and its pod is up - the only two things the start waited
    // for.
    await startPaneDetached(workspace, conversation.id);
    onNote?.('the conversation has started');
    // Sharing by default happens when the workspace is opened (WorkspaceConversations), not
    // here: a build beside an agent that has just started is two compiles on one node.
    void store;
  };

  // A pod that is up is prepared now, before this returns: a page that navigates away a
  // moment after the click would otherwise take the preparation with it and leave a
  // conversation with nothing queued. Only a pod that does not exist yet is waited for in the
  // background, since that wait is minutes and the pane shows it arriving.
  //
  // Reported, never thrown. The conversation above exists by the time this runs, so a caller
  // that turned this into a failure was telling the truth about the preparation and lying
  // about everything else: the button went red, the page did not navigate, and the
  // conversation it had just made was left sitting in the workspace unmentioned. Pressing the
  // button again then made a second one. The background branch below has always swallowed the
  // same failure - `ensureWorkspaceReady` installs tools with apt and clones a checkout, and
  // either can fail on a workspace that is otherwise perfectly usable - so this is the two
  // branches agreeing rather than a failure being hidden.
  if (await workspacePod(workspace).catch(() => null)) {
    try {
      await prepare();
    } catch (e: Json) {
      onNote?.(`the workspace could not be prepared: ${ e?.message || e }`);
      note('dev', 'preparing the workspace failed', e);
    }

    return conversation;
  }

  (async() => {
    try {
      await wakeWorkspace(workspace, onNote);
      onNote?.('waiting for the workspace pod');
      await waitForWorkspacePod(workspace);
      await prepare();
    } catch (e: Json) {
      onNote?.(`could not start: ${ e?.message || e }`);
      note('dev', 'preparing the workspace failed', e);
    }
  })();

  return conversation;
}

/**
 * A conversation to talk in, for a workspace that has none.
 *
 * "Ask the agent" opened the conversation window and stopped there, which is right when there
 * is a conversation in it and an empty black rectangle when there is not - and a workspace made
 * for a pull request that already exists has a stage, a rail, and no agent that has ever run in
 * it. So the window it opens is given something to show: the same start every other action
 * makes, with nothing queued, so whoever pressed it can type.
 */
export async function openConversation(workspace: string, title = 'Conversation', onNote?: (note: string) => void, from: ConversationOrigin = ''): Promise<ProjectConversation> {
  const existing = await listConversations(workspace).catch(() => [] as ProjectConversation[]);

  /*
   * The one with this title if there is one, and otherwise the conversation that is already here.
   *
   * This matched on the title alone for a while, creating a new conversation when none matched -
   * and in a workspace whose conversations are called `Review #19153` or `Discuss comment #8`,
   * nothing ever matches `Conversation`. So asking the agent minted an empty conversation and the
   * pane switched to it: what you were reading flashed and was replaced by a blank one, which is
   * how it was reported and exactly what it was.
   *
   * The title is still preferred, because a caller that names one means it. What changed back is
   * the fallback: an existing conversation is reused rather than a new one made. Creating is the
   * last resort it always was, for a workspace that genuinely has none.
   *
   * The hazard that prompted the title match is real but much smaller than this was: `existing[0]`
   * is the oldest, which in a `pr-<n>` workspace is the review's own pane, so a general question
   * can land in a review mid-pass. That is worth fixing where the conversation is chosen for a
   * specific purpose - `startPrReview` and `startIssueFix` already match on title themselves - and
   * is not worth a new conversation on every ask.
   */
  const found = existing.find((conversation) => conversation.title === title) || existing[0];

  return found || openWith(workspace, title, '', undefined, onNote, undefined, from);
}

export interface Started {
  workspace: string;
  conversation: ProjectConversation;
  created: boolean;
  /**
   * Start fix only: the issue's board status once starting moved it to Working (or found it
   * further along), null when it is on no board with a Working column, and `boardError` when
   * GitHub refused - a token without `project` scope, most often.
   */
  board?: GithubBoardStatus | null;
  boardError?: string;
}

const sweepAttempted = new Map<string, number>();
let sweeping = false;

/**
 * Start every conversation that was told what to do and never began, whose workspace is up.
 *
 * `openWith` starts the pane itself once the pod is up, but only while the page that pressed
 * the button is still open: a reload, a closed tab, a Rancher that restarted under the wait,
 * and the prompt sat in its queue until somebody opened the conversation. This runs on the
 * sidebar's poll instead, so any page of the product, open at any later time, finishes the
 * job: the workspace is prepared (cheap when it already is) and the pane started, detached.
 * Once per workspace every few minutes, so a preparation that fails is not retried on every
 * poll, and never two at once.
 */
export async function startPendingConversations(workspaces: { name: string; state: string }[]): Promise<void> {
  if (sweeping) {
    return;
  }
  sweeping = true;
  try {
    const pending = await queuedNotStarted();
    const running = new Set(workspaces.filter((w) => w.state === 'running').map((w) => w.name));
    const now = Date.now();

    for (const workspace of new Set(pending.map((p) => p.workspace))) {
      if (!running.has(workspace) || now - (sweepAttempted.get(workspace) || 0) < 5 * 60_000) {
        continue;
      }
      sweepAttempted.set(workspace, now);
      try {
        await ensureWorkspaceReady(workspace);
        for (const { id } of pending.filter((p) => p.workspace === workspace)) {
          await startPaneDetached(workspace, id);
        }
      } catch (e) {
        note('dev', `starting the queued conversations of ${ workspace } failed`, e);
      }
    }
  } finally {
    sweeping = false;
  }
}

/**
 * The workspace a PR action (review, CI triage) works in: named for the PR, always.
 *
 * It used to fold a PR that closes an issue into that issue's workspace, `issue-<n>`, so a fix
 * and the review of its PR shared one pod. But a review is its own piece of work and reads as its
 * own project - `pr-<n>` - so reviewing #123 makes `pr-123` whether or not it happens to close an
 * issue, rather than reopening the issue's workspace under a name that does not mention the PR.
 */
export function prWorkspaceName(pr: { number: number; issue?: { number: number } | null }): string {
  return `pr-${ pr.number }`;
}

/**
 * Review a PR: the harness's "Review" button. Reattaches to a review already running.
 *
 * `ask` false is the same button pressed by an automation (agent-defs.ts, claimReviews): no Rancher
 * picker for a new workspace, since nobody is there to answer it.
 */
export async function startPrReview(store: Store, pr: { number: number; title?: string; issue?: { number: number } | null }, repo = DEFAULT_REPO, inWorkspace = '', ask = true): Promise<Started> {
  const workspace = inWorkspace || await workspaceFor(prWorkspaceName(pr));
  const created = await ensureWorkspace(store, workspace, pr.title || '', repo, ask);
  const title = `Review #${ pr.number }`;
  const existing = (await listConversations(workspace).catch(() => [])).find((c) => c.title === title);

  if (existing) {
    await deliverTo(workspace, existing, reviewPrompt(pr.number, repo));

    return { workspace, conversation: existing, created };
  }

  const conversation = await openWith(workspace, title, reviewPrompt(pr.number, repo), { pr: pr.number, issue: pr.issue?.number || null },
    (note) => setReviewRun(pr.number, 'starting', note, workspace).catch(() => {}), store, `pr-${ pr.number }-review`);

  await setReviewRun(pr.number, 'starting', 'conversation opened; waiting for the workspace', workspace).catch(() => {});

  return { workspace, conversation, created };
}

/**
 * Fix an issue: the harness's "Start fix". Reattaches to a fix already running.
 *
 * The reattach is what startPrReview and startDependabotReview have always done and this did
 * not, which made Start fix the one button here that answered a second press by starting a
 * second conversation about the same issue. The workspace was already shared - it is named for
 * the issue - so what came of pressing it twice was one workspace holding two "Fix #18264"
 * panes, both queued with the same prompt, racing each other over one checkout.
 */
export async function startIssueFix(store: Store, issue: { number: number; title: string }, repo = DEFAULT_REPO): Promise<Started> {
  // The board says somebody has picked it up: Working, unless it is already past that (see
  // setIssueStatus). Here rather than in one page, because a fix is started from My Work, from
  // Focus and from the workspace itself, and the board should not depend on which. Asked for
  // first and awaited last, so it costs the button no time; it never fails the fix.
  const boardSoon = setIssueStatus(repo, issue.number).then(
    (board) => ({ board, boardError: '' }),
    (e: Json) => ({ board: null, boardError: e?.message || String(e) }),
  );
  const workspace = await workspaceFor(`issue-${ issue.number }`);
  const created = await ensureWorkspace(store, workspace, issue.title || '', repo);
  const title = `Fix #${ issue.number }`;
  const existing = (await listConversations(workspace).catch(() => [])).find((c) => c.title === title);

  if (existing) {
    await deliverTo(workspace, existing, fixPrompt(issue.number, repo));

    return {
      workspace, conversation: existing, created, ...await boardSoon
    };
  }

  const conversation = await openWith(workspace, title, fixPrompt(issue.number, repo), { issue: issue.number }, undefined, store, `issue-${ issue.number }-fix`);

  return {
    workspace, conversation, created, ...await boardSoon
  };
}

/**
 * Run one step of Jira triage on a bug: the harness's "Review", "Reproduce", "Unstick", "Fix".
 *
 * A workspace named for the bug, and a conversation in it running that step's skill. The harness
 * split this in two - a step that only read Jira ran in its own CLI container, which held the
 * token and the API - and that half has nowhere to go here: the agent pod has neither
 * `$CLAUDE_HARNESS_API` nor a checkout, so a conversation started outside a workspace could not
 * reach the Jira routes at all. So every step runs in `…sure-<n>`, and what separates reproducing
 * and fixing from the other two is the tools they attach once they are in it.
 *
 * Reattaches like the rest: a second press on the same step sends the prompt to the conversation
 * that is already doing it rather than starting a second one over the same ticket.
 */
export async function startJiraTriage(store: Store, bug: { key: string; summary?: string; status?: string }, action: string, repo = DEFAULT_REPO): Promise<Started> {
  const step = TRIAGE_ACTIONS[action];

  if (!step) {
    throw new Error(`"${ action }" is not a triage step.`);
  }
  const key = bug.key.toUpperCase();
  const workspace = await workspaceFor(jiraWorkspaceName(key));
  const created = await ensureWorkspace(store, workspace, bug.summary || key, repo);

  // Which group the nav puts it in, written on every run rather than at create: the same
  // workspace is a review this morning and a reproduction this afternoon, and its name cannot
  // say which. See roleForStep.
  await setWorkspaceRole(workspace, roleForStep(action));

  const title = `${ step.label } ${ key }`;
  const existing = (await listConversations(workspace).catch(() => [])).find((c) => c.title === title);
  const prompt = jiraPrompt(key, action);

  if (existing) {
    await deliverTo(workspace, existing, prompt);

    return { workspace, conversation: existing, created };
  }

  const conversation = await openWith(workspace, title, prompt, undefined, undefined, store, `${ key.toLowerCase() }-${ action }`);

  // Started, so the queue's row can say so before the pane has drawn anything. The skill reports
  // its own states over the same route from then on.
  await api(`/my-work/jira/${ key }/run/${ action }`, {
    method:  'POST',
    headers: { 'content-type': 'application/json' },
    body:    JSON.stringify({ state: 'starting', workspace, note: `${ step.label } started from My Work` }),
  }).catch(() => {});

  return { workspace, conversation, created };
}

/**
 * What the step is told, in prose rather than as `/my-jira-bug-…` - see reviewPrompt: a leading
 * slash is swallowed as an unknown CLI command when this is typed into a running pane.
 */
export function jiraPrompt(key: string, action: string): string {
  const step = TRIAGE_ACTIONS[action];
  const api = `$CLAUDE_HARNESS_API/my-work/jira/${ key }`;

  return `Use the ${ step.skill } skill on ${ key }. The ticket, its comments and its attachments: ${ api }/detail. `
    + `File what you conclude for a person to approve with POST ${ api }/recommendation, and report where you are with POST ${ api }/run/${ action }.`;
}

export function alertWorkspaceName(group: { packages: string[]; slug: string }): string {
  const pkg = (group.packages[0] || group.slug).replace(/^@/, '').replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase();

  return `dependabot-${ pkg }`.replace(/-+$/, '').slice(0, 40);
}

/** Fix a Dependabot advisory: the harness's "Start fix" on an alert group. */
export async function startAlertFix(store: Store, group: Json, repo = DEFAULT_REPO): Promise<Started> {
  const workspace = await workspaceFor(alertWorkspaceName(group));
  const created = await ensureWorkspace(store, workspace, '', repo);
  const title = `Fix ${ group.packages[0] || group.slug }`;
  const existing = (await listConversations(workspace).catch(() => [])).find((c) => c.title === title);

  const alertList = (group.alerts || []).map((a: Json) => `#${ a.number } ${ a.packageName } in ${ a.manifest }`).join('; ');
  const alertPrompt = `/my-dependabot-fix ${ JSON.stringify(group.title) } — ${ (group.alerts || []).length } open alert(s): ${ alertList }. The advisories: $CLAUDE_HARNESS_API/my-work/dependabot.`;

  if (existing) {
    await deliverTo(workspace, existing, alertPrompt);

    return { workspace, conversation: existing, created };
  }

  const conversation = await openWith(workspace, title, alertPrompt, undefined, undefined, undefined, `alert-${ group.slug || group.packages?.[0] || '' }-fix`);

  return { workspace, conversation, created };
}

/** Review a Dependabot PR: the harness's merge checklist, ending in MERGE or STOP. */
export async function startDependabotReview(store: Store, pr: { number: number }, repo = DEFAULT_REPO): Promise<Started> {
  const workspace = await workspaceFor(`pr-${ pr.number }`);
  const created = await ensureWorkspace(store, workspace, '', repo);
  const title = `Dependabot review #${ pr.number }`;
  const existing = (await listConversations(workspace).catch(() => [])).find((c) => c.title === title);
  const reviewText = `/my-dependabot-review Review ${ repo } PR #${ pr.number } — a dependabot bump. Its full context: curl -s "$CLAUDE_HARNESS_API/my-work/dependabot/pr/${ pr.number }/review-context". Finish with MERGE or STOP alone on the last line.`;
  const conversation = existing || await openWith(workspace, title, reviewText, { pr: pr.number }, undefined, undefined, `dependabot-pr-${ pr.number }-review`);

  if (existing) {
    await deliverTo(workspace, existing, reviewText);
  }

  await api(`/my-work/dependabot/reviews/${ pr.number }`, {
    method: 'PUT',
    body:   JSON.stringify({
      workspace, conversation: conversation.id, state: existing ? 'running' : 'starting', verdict: null, reason: '', startedAt: new Date().toISOString(),
    }),
  }).catch(() => {});

  return { workspace, conversation, created };
}

/** Triage red CI: the first step of the harness's smart rerun, as a conversation. */
export async function startCiTriage(store: Store, pr: { number: number; title?: string; issue?: { number: number } | null }, repo = DEFAULT_REPO, inWorkspace = ''): Promise<Started> {
  const workspace = inWorkspace || await workspaceFor(prWorkspaceName(pr));
  const created = await ensureWorkspace(store, workspace, pr.title || '', repo);
  const failures = await ciFailures(pr.number, repo).catch(() => ({ checks: [] }));
  const details = (failures.checks || []).slice(0, 6).map((c: Json) => `- ${ c.name }: ${ c.conclusion }${ c.title ? ` - ${ c.title }` : '' }${ c.summary ? `\n  ${ c.summary.slice(0, 300) }` : '' } (${ c.url })`).join('\n');
  const conversation = await openWith(workspace, `CI #${ pr.number }`,
    // Named in prose, not as `/my-ci-triage`: a pane's claude answers "Unknown command" to a
    // `/<skill>` it has no registered command for, and the prompt never reaches the model. Same for
    // the my-ci-fix reference below. See workspace-rail's skillTemplate.
    `Use the my-ci-triage skill. ${ repo } PR #${ pr.number } is red. The failing checks:\n\n${ details || '(read them from $CLAUDE_HARNESS_API/my-work/pr/' + pr.number + '/ci)' }\n\nDecide whether this PR's own change caused them. If they are ours, fix them with the my-ci-fix skill, verify, commit and push; if not, re-run the failed jobs with gh. Finish with OURS or FLAKE alone on the last line.`,
    undefined, undefined, undefined, `pr-${ pr.number }-ci-triage`);

  return { workspace, conversation, created };
}

/** The opening prompt of a discussion about one pending comment: the harness's, with this API in it. */
/**
 * What a discussion opened quietly says where the visible one said "anything after this sentence
 * is their question": the person's messages arrive on their own, after this, as the conversation.
 */
const QUIET_OPENER = ' The user\'s messages in this conversation are their side of it: answer what they say, and do not repeat this context back to them.';

/** A discussion's opening, marked as context the dashboard gave rather than words the person typed. */
export function quietContext(text: string): string {
  return `Context for this conversation, set by the dashboard it was opened from - the user did not type this and does not see it. ${ text }`;
}

/**
 * Typed to the four fields it reads, so a caller that has a note rather than a comment can pass one.
 *
 * It took a whole `LocalComment`, and the Focus deck's Discuss has a `ReviewNote` - so that call
 * site cast with `as never`, and the cast silenced the argument check as well as the shape check.
 * Its arguments were the wrong way round: the comment went in as `num` and the pull request number
 * went in as `comment`. Every Discuss on every review card sent the agent "pending review comment
 * #undefined on rancher/dashboard PR #[object Object] - a PR-level comment: \"undefined\"", with a
 * `curl` for PR `[object Object]` and a `PUT` to `comments/undefined`. Nothing it was told was
 * true, and the type that would have said so had been cast away.
 *
 * A `Pick` rather than the whole interface is what lets the cast go, which is the part that
 * matters: the other two callers were always correct, so it was never the order that was fragile.
 */
export function discussPrompt(
  num: number,
  comment: Pick<LocalComment, 'id' | 'body' | 'path' | 'line'>,
  message: string,
  repo = DEFAULT_REPO,
  /**
   * Where this comment actually lives, because the agent is told how to change it.
   *
   * `'local'` is a finding in dev-api's own store, which the agent can edit and drop over the
   * harness API - the routes below. `'github'` is a reply of yours drafted in an unsubmitted
   * GitHub review, and the harness API does not hold it: the same `PUT` would 404 on an id that
   * store has never seen, and - far worse - the `DELETE` would match nothing, delete nothing and
   * answer `{"ok":true}`, so the agent would tell you it had dropped a draft that is still on
   * GitHub for you to submit. An agent that reports work it did not do is the one failure here
   * that costs more than doing nothing, so a GitHub comment is given no write routes at all and
   * told plainly to hand the wording back.
   */
  lives: 'local' | 'github' | 'draft' = 'local',
  /** Given as hidden context rather than said as the first message: see stageSessionContext. */
  quiet = false,
): string {
  const oneline = String(comment.body).replace(/\s+/g, ' ').slice(0, 400);
  const where = comment.path ? `file ${ comment.path }${ comment.line ? `, line ${ comment.line }` : '' }` : 'a PR-level comment';
  const opener = quiet
    ? QUIET_OPENER
    : message
      ? ` The user's opening message about it: "${ message.replace(/\s+/g, ' ').slice(0, 600) }" — address that directly first.`
      : ' Anything after this sentence is their question — answer that; if there is nothing there, start with your read of the code in question and whether the comment holds up.';
  const apiHint = API_HINT;
  const subject = lives === 'github'
    ? `the user's own unsubmitted reply (GitHub review comment #${ comment.id })`
    : lives === 'draft'
      ? `reply draft #${ comment.id }, an unposted answer drafted into a review thread for the user to send`
      : `pending review comment #${ comment.id }`;
  /*
   * A drafted reply is in the harness API's own store (reply-drafts), so unlike a GitHub draft
   * the agent can rewrite it - and must not post it: sending is the person's, from the panel.
   */
  const ending = lives === 'draft'
    ? ` The draft and the thread it answers: curl -s ${ apiHint }/${ num }/reply-drafts and curl -s ${ apiHint }/${ num }/threads. When the user settles on improved wording, update the draft: curl -s -X PUT ${ apiHint }/${ num }/reply-drafts/${ comment.id } -H 'Content-Type: application/json' -d '{"body":"<new text>"}'. If they decide to drop it: curl -s -X DELETE ${ apiHint }/${ num }/reply-drafts/${ comment.id }. Never post it or any other reply to GitHub yourself — the user sends it from the panel.`
    : lives === 'github'
    ? ` This comment is a draft in the user's unsubmitted review on GitHub, not in the harness API, so you cannot change or delete it yourself and must not try — there is no route that would work, and the delete route for harness findings answers "ok" without deleting anything of GitHub's. When the user settles on improved wording, give them the final text in a fenced block and tell them to paste it into Edit on that reply.`
    : ` When the user settles on improved wording, update the comment: curl -s -X PUT ${ apiHint }/${ num }/comments/${ comment.id } -H 'Content-Type: application/json' -d '{"body":"<new text>"}'. If they decide to drop it: curl -s -X DELETE ${ apiHint }/${ num }/comments/${ comment.id }.`;

  const said = `The user wants to discuss ${ subject } on ${ repo } PR #${ num } — ${ where }: "${ oneline }". Fetch the PR for context with: curl -s ${ apiHint }/${ num } (find the relevant hunk in files[].patch${ comment.path ? ` for ${ comment.path }` : '' }).${ opener } Keep responses conversational and concise — this is a live discussion.${ ending }`;

  return quiet ? quietContext(said) : said;
}

/** The opening prompt of a discussion about some lines, with no comment filed. */
export function linesPrompt(num: number, lines: { path: string; line: number; startLine: number | null; side: string; code?: string }, message: string, repo = DEFAULT_REPO, quiet = false): string {
  const range = lines.startLine ? `lines ${ lines.startLine }-${ lines.line }` : `line ${ lines.line }`;
  const apiHint = API_HINT;
  const code = (lines.code || '').slice(0, 4000);
  const opener = quiet
    ? QUIET_OPENER
    : message
      ? ` Their opening message: "${ message.replace(/\s+/g, ' ').slice(0, 600) }" — address it directly.`
      : ' Anything after this sentence is their question — answer that; if there is nothing there, start with your read of that code.';
  const said = `The user is reviewing ${ repo } PR #${ num } and wants to discuss ${ lines.path } ${ range } (${ lines.side } side of the diff). Fetch the PR with: curl -s ${ apiHint }/${ num } and find that file in files[].patch for context.${ code ? ` The selected lines are:\n\n${ code }\n` : '' }${ opener } Keep it conversational. Do NOT file a review comment unless the user asks; if they do, run: curl -s -X POST ${ apiHint }/${ num }/comments -H 'Content-Type: application/json' -d '{"path":"${ lines.path }","line":${ lines.line }${ lines.startLine ? `,"startLine":${ lines.startLine }` : '' },"side":"${ lines.side }","body":"<comment>"}'`;

  return quiet ? quietContext(said) : said;
}

/**
 * The opening prompt of a discussion about the conclusion a triage step reached.
 *
 * The conclusion was read-only, then editable by hand (`amendJiraRecommendation`), and neither
 * covers the case that actually comes up: it is nearly right, and what is wrong about it is a
 * thing the agent knows and the person does not - which version it reproduced on, what the
 * reporter's log actually said. That is a conversation, not a textarea.
 *
 * So the agent is told what it concluded and given the route that corrects it. The two halves
 * then compose: talk it through, let the agent put the proposal right, and "Fill the form in
 * with it" picks up the corrected text. Nothing here may touch the ticket - the approval step is
 * the one the process requires, and an agent that commented during a discussion about whether to
 * comment is the crossover the runbook forbids.
 */
export function conclusionPrompt(key: string, rec: { action?: string; reason?: string; comment?: string } | null, message: string, quiet = false): string {
  const api = `$CLAUDE_HARNESS_API/my-work/jira/${ key }`;
  const flat = (text: string, cap: number) => String(text || '').replace(/\s+/g, ' ').slice(0, cap);
  const opener = quiet
    ? QUIET_OPENER
    : message
      ? ` The user's opening message about it: "${ flat(message, 600) }" - address that directly first.`
      : ' Anything after this sentence is their question - answer that; if there is nothing there, start with the part of your conclusion you are least sure of.';
  const said = [
    `The user wants to discuss the conclusion a triage step reached about ${ key }, which is pending their approval.`,
    rec?.action ? ` It proposes: ${ flat(rec.action, 120) }.` : '',
    rec?.reason ? ` Its conclusion, which Apply posts to the ticket verbatim as the comment the reporter reads: "${ flat(rec.reason, 1200) }".` : '',
    ` Read the ticket for context with: curl -s ${ api }/detail`,
    `, and the proposal as stored with: curl -s ${ api }/recommendation.`,
    opener,
    ' Keep it conversational and concise - this is a live discussion, and nothing said here reaches the reporter.',
    ` When the user settles on better wording, correct the proposal in place: curl -s -X PUT ${ api }/recommendation -H 'Content-Type: application/json' -d '{"reason":"<the conclusion, written for the reporter>"}'. It is posted word for word, so keep anything only the user needs in this conversation.`,
    ' That amends the proposal and nothing else - the person still presses Apply, which is what writes to the ticket.',
    ` Do NOT move ${ key }, comment on it, or POST a new recommendation yourself.`,
  ].join('');

  return quiet ? quietContext(said) : said;
}

/**
 * A discussion about one bug's pending conclusion, in that bug's own workspace.
 *
 * Titled `Discuss <KEY>` because that is the shape the rail's strip filters on: a discussion
 * belongs under the thing it is about, not as another tab across the top. See railConversations.
 */
export async function startConclusionDiscussion(
  workspace: string, key: string, rec: { action?: string; reason?: string; comment?: string } | null, message = '',
): Promise<ProjectConversation> {
  const bug = key.toUpperCase();

  return startDiscussion(workspace, `Discuss ${ bug }`, conclusionPrompt(bug, rec, '', true), { label: `${ bug.toLowerCase() }-conclusion` }, message);
}

/**
 * A discussion: a conversation in the workspace that knows what it is about, the pod made ready.
 *
 * `context` is what the agent is told - the comment, the lines, the routes it may use - and it is
 * given quietly (stageSessionContext), so the chat opens on nothing but what the person says.
 * `message` is the person's own first words when they typed some before it opened; it is queued
 * as the opening prompt and is all the chat shows of the start. With no message the conversation
 * waits for one, and the context goes with it.
 */
export async function startDiscussion(workspace: string, title: string, context: string, from: ConversationOrigin = '', message = ''): Promise<ProjectConversation> {
  return openWith(workspace, title, message.trim(), undefined, undefined, undefined, from, context);
}

/**
 * The workspace made ready for whatever a person types, as its page opens: the same preparation
 * an action gets, unless the workspace's stamp says it has had it.
 */
export async function prepareWorkspace(workspace: string): Promise<void> {
  await ensureWorkspaceOnOpen(workspace);
}

/** Say something into a running conversation: queued the same way, read by the pane's runner. */
export async function sayInConversation(conversation: ProjectConversation, message: string): Promise<void> {
  await queuePrompt(conversation.attach, message);
}

/**
 * End a review: the conversation and every process in it, and the run marked cancelled so the
 * panel stops waiting. The comments it filed stay.
 */
export async function cancelReview(num: number, workspace: string, conversationId: string | null): Promise<ReviewRun> {
  if (conversationId) {
    await endConversation(workspace, conversationId).catch(() => {});
  }

  return setReviewRun(num, 'cancelled', 'Cancelled - the agent and its subagents were stopped', workspace);
}

// ── Verdicts, read off a pane ───────────────────────────────────────────────────────────────

function cleanPaneLine(line: string): string {
  return line
    .replace(/[─-╿]/g, ' ')
    .replace(/^[\s>·*⏺●✻✽◯◉⎿→←]+/, '')
    .replace(/\s+$/, '')
    .trim();
}

export function verdictFromPane(pane: string, words: string[] = ['MERGE', 'STOP']): { verdict: string | null; reason: string } {
  const all = pane.split('\n').map(cleanPaneLine);
  const verdictRe = new RegExp(`^(${ words.join('|') })[.!]?$`);
  const furniture = (t: string) => /^(esc to interrupt|\? for shortcuts|bypass permissions|\/my-|Churned for|Cooked for|✻|●|Try ")/i.test(t);
  const listItem = (t: string) => /^\d+\.\s/.test(t) || /^#{1,6}\s/.test(t) || /^[-*]\s/.test(t);

  for (let i = all.length - 1; i >= 0; i--) {
    const m = all[i].match(verdictRe);

    if (!m) {
      continue;
    }

    let j = i - 1;
    const skippable = (t: string) => !t || furniture(t) || verdictRe.test(t);

    while (j >= 0 && skippable(all[j])) {
      j--;
    }

    const para: string[] = [];

    for (; j >= 0; j--) {
      const text = all[j];

      if (!text || furniture(text) || verdictRe.test(text)) {
        break;
      }
      para.unshift(text);
      if (listItem(text)) {
        break;
      }
    }

    return { verdict: m[1].toLowerCase(), reason: para.join(' ').replace(/\s+/g, ' ').trim().slice(0, 500) };
  }

  return { verdict: null, reason: '' };
}

const BUSY_RE = /esc to interrupt|Interrupt ·|tokens · esc|⏳|Thinking…|Working…/i;

export interface BotReview {
  pr: number;
  workspace: string;
  conversation: string;
  state: 'starting' | 'running' | 'done' | 'ended';
  verdict: 'merge' | 'stop' | null;
  reason: string;
  startedAt: string;
  updatedAt: string;
}

export async function dependabotReviews(): Promise<Record<string, BotReview>> {
  return (await api('/my-work/dependabot/reviews'))?.reviews || {};
}

export async function closeDependabotReview(num: number): Promise<void> {
  await api(`/my-work/dependabot/reviews/${ num }`, { method: 'DELETE' });
}

/** Read one bot review's pane and record what it says. */
export async function refreshDependabotReview(review: BotReview, attach: Attachment): Promise<BotReview> {
  const pane = await conversationPane(attach.workspace, attach.id, 80).catch(() => ({ text: '', running: false }));
  const { verdict, reason } = verdictFromPane(pane.text);
  const busy = BUSY_RE.test(pane.text);
  const state: BotReview['state'] = verdict ? 'done' : (pane.running ? (busy ? 'running' : 'ended') : review.state);
  const next = {
    ...review, state, verdict: (verdict as BotReview['verdict']) || review.verdict, reason: reason || review.reason,
  };

  if (next.state !== review.state || next.verdict !== review.verdict) {
    await api(`/my-work/dependabot/reviews/${ review.pr }`, { method: 'PUT', body: JSON.stringify(next) }).catch(() => {});
  }

  return next;
}

export async function dependabotData(repo = DEFAULT_REPO): Promise<Json> {
  return api(`/my-work/dependabot?repo=${ encodeURIComponent(repo) }`);
}

export { listConversations };

/**
 * One file from a workspace onto GitHub's `user-attachments`, as the markdown that embeds it:
 * an image inline, a recording as the bare URL GitHub turns into a player.
 *
 * The upload goes through the shared signed-in browser (the in-cluster API does it) because
 * `user-attachments` is a browser flow, not an API one.
 */
export async function attachToPr(num: number, path: string, repo = DEFAULT_REPO): Promise<{ href: string; embed: string; name: string; kind: string }> {
  const result = await api(`/my-work/pr/${ num }/upload`, { method: 'POST', body: JSON.stringify({ path, repo }) }) as Json;
  const href = result?.href || '';

  if (!href) {
    throw new Error(`${ path } could not be uploaded to GitHub.`);
  }
  const name = result.name || path.split('/').pop() || 'attachment';

  return {
    href, name, kind: result.kind || '', embed: result.kind === 'video' ? href : `![${ name }](${ href })`,
  };
}

